    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Global row and column for the C element
    int row = by * TILE_DIM + ty;
    int col = bx * TILE_DIM + tx;

    float C_value = 0.0f;

    // Loop over the tiles of A and B required to compute the C tile
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A from global memory to shared memory
        if (row < N && (t * TILE_DIM + tx) < N) {
            sA[ty][tx] = A[row * N + (t * TILE_DIM + tx)];
        } else {
            sA[ty][tx] = 0.0f;
