            sB[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        // Synchronize to make sure the tiles are loaded
        __syncthreads();

        // Compute the dot product for the C element
        for (int k = 0; k < TILE_DIM; ++k) {
            C_value += sA[ty][k] * sB[k][tx];
